# Building Custom Spark SharePoint Connector

Creating a custom Apache Spark data source for Microsoft SharePoint using Python Data Source API v2 requires integrating multiple sophisticated technologies. This comprehensive guide provides detailed implementation patterns, authentication strategies, error handling, and performance optimization techniques for building a production-ready SharePoint connector.

## Authentication foundation with service principal

The SharePoint integration begins with **Azure AD service principal authentication**, which provides secure, scalable access to SharePoint resources. This modern approach supersedes legacy authentication methods and integrates seamlessly with Microsoft's cloud ecosystem.

**Core authentication implementation** centers on the Microsoft Authentication Library (MSAL), which handles token acquisition, refresh, and management. The service principal requires three key credentials: ClientID, ClientSecret, and TenantID, obtained through Azure AD app registration with appropriate SharePoint permissions.

```python
from msal import ConfidentialClientApplication
import requests
from typing import Optional, Dict
import threading
from datetime import datetime, timedelta

class SharePointAuthenticator:
    def __init__(self, client_id: str, client_secret: str, tenant_id: str):
        self.client_id = client_id
        self.client_secret = client_secret
        self.tenant_id = tenant_id
        self.authority = f"https://login.microsoftonline.com/{tenant_id}"

        self.app = ConfidentialClientApplication(
            client_id=client_id,
            client_credential=client_secret,
            authority=self.authority
        )

        self._token_cache = {}
        self._token_lock = threading.Lock()

    def get_access_token(self, resource_url: str) -> str:
        """Get valid access token for SharePoint resource"""
        scope = f"{resource_url}/.default"

        with self._token_lock:
            # Check cached token validity
            if self._is_token_valid(scope):
                return self._token_cache[scope]['token']

            # Acquire new token
            result = self.app.acquire_token_for_client(scopes=[scope])

            if 'access_token' in result:
                self._cache_token(scope, result)
                return result['access_token']
            else:
                raise Exception(f"Authentication failed: {result.get('error_description')}")

    def _is_token_valid(self, scope: str) -> bool:
        """Check if cached token is still valid"""
        if scope not in self._token_cache:
            return False

        token_info = self._token_cache[scope]
        buffer_time = timedelta(minutes=5)
        return datetime.now() + buffer_time < token_info['expires_at']

    def _cache_token(self, scope: str, token_result: Dict):
        """Cache token with expiration info"""
        expires_in = token_result.get('expires_in', 3600)
        self._token_cache[scope] = {
            'token': token_result['access_token'],
            'expires_at': datetime.now() + timedelta(seconds=expires_in)
        }
```

The authentication layer handles **automatic token refresh** and caching to minimize API calls. Production implementations should store client secrets securely using Azure Key Vault or similar services, never hardcoding credentials in source code.

## SharePoint REST API integration patterns

SharePoint's REST API provides comprehensive access to document libraries, files, and metadata through structured endpoints. The **modern REST API structure** follows consistent patterns for different operations, enabling programmatic access to SharePoint content.

```python
import requests
from typing import List, Dict, Iterator, Optional
import json
from urllib.parse import quote

class SharePointAPIClient:
    def __init__(self, site_url: str, authenticator: SharePointAuthenticator):
        self.site_url = site_url.rstrip('/')
        self.authenticator = authenticator
        self.api_base = f"{self.site_url}/_api"

    def _get_headers(self) -> Dict[str, str]:
        """Get authenticated request headers"""
        token = self.authenticator.get_access_token(self.site_url)
        return {
            'Authorization': f'Bearer {token}',
            'Accept': 'application/json;odata=verbose',
            'Content-Type': 'application/json;odata=verbose'
        }

    def list_files(self, library_name: str, folder_path: str = None) -> List[Dict]:
        """List files in SharePoint library or folder"""
        if folder_path:
            encoded_path = quote(folder_path, safe='')
            endpoint = f"{self.api_base}/web/GetFolderByServerRelativeUrl('{encoded_path}')/Files"
        else:
            endpoint = f"{self.api_base}/web/lists/getbytitle('{library_name}')/items"
            endpoint += "?$select=Title,Modified,Author/Title,FileRef,FileLeafRef,File/Length"
            endpoint += "&$expand=Author,File"

        response = requests.get(endpoint, headers=self._get_headers(), timeout=30)
        response.raise_for_status()

        data = response.json()
        if 'odata' in data:
            return data['d']['results']
        return data.get('d', {}).get('results', [])

    def download_file(self, file_url: str) -> bytes:
        """Download file content from SharePoint"""
        encoded_url = quote(file_url, safe='')
        endpoint = f"{self.api_base}/web/GetFileByServerRelativeUrl('{encoded_url}')/$value"

        response = requests.get(endpoint, headers=self._get_headers(), timeout=60)
        response.raise_for_status()
        return response.content

    def upload_file(self, library_name: str, file_name: str, content: bytes) -> Dict:
        """Upload file to SharePoint library"""
        endpoint = f"{self.api_base}/web/lists/getbytitle('{library_name}')/RootFolder/Files"
        endpoint += f"/add(url='{quote(file_name)}',overwrite=true)"

        headers = self._get_headers()
        headers['Content-Length'] = str(len(content))

        response = requests.post(endpoint, headers=headers, data=content, timeout=120)
        response.raise_for_status()
        return response.json()

    def batch_operations(self, operations: List[Dict]) -> List[Dict]:
        """Execute multiple operations in a single batch request"""
        boundary = f"batch_{datetime.now().isoformat()}"
        batch_body = self._build_batch_body(operations, boundary)

        headers = self._get_headers()
        headers['Content-Type'] = f'multipart/mixed; boundary={boundary}'

        response = requests.post(
            f"{self.api_base}/$batch",
            headers=headers,
            data=batch_body,
            timeout=180
        )
        response.raise_for_status()
        return self._parse_batch_response(response.text)
```

**Batch operations** significantly improve performance when processing multiple files or folders. The SharePoint REST API supports OData batch requests that can combine multiple operations into a single HTTP request, reducing network overhead and improving throughput.

## Spark Python Data Source API v2 implementation

The **Python Data Source API v2** in Spark 4.0+ provides a clean, Python-native approach to building custom data sources. This API eliminates the need for Java/Scala knowledge while providing full access to Spark's distributed processing capabilities.

```python
from pyspark.sql.datasource import DataSource, DataSourceReader, InputPartition
from pyspark.sql.types import StructType, StructField, StringType, IntegerType, TimestampType, LongType
from typing import Iterator, List, Tuple
import pyarrow as pa

class SharePointDataSource(DataSource):
    """Custom Spark data source for SharePoint integration"""

    @classmethod
    def name(cls):
        return "sharepoint"

    def schema(self):
        return StructType([
            StructField("file_name", StringType(), False),
            StructField("file_path", StringType(), False),
            StructField("file_size", LongType(), True),
            StructField("modified_date", TimestampType(), True),
            StructField("content_type", StringType(), True),
            StructField("content", StringType(), True)
        ])

    def reader(self, schema: StructType):
        return SharePointDataSourceReader(self.options, schema)

class SharePointInputPartition(InputPartition):
    """Represents a partition of SharePoint files to process"""

    def __init__(self, partition_id: int, file_list: List[Dict], partition_params: Dict):
        super().__init__()
        self.partition_id = partition_id
        self.file_list = file_list
        self.partition_params = partition_params

class SharePointDataSourceReader(DataSourceReader):
    """Reads data from SharePoint with partitioning support"""

    def __init__(self, options: Dict[str, str], schema: StructType):
        self.options = options
        self.schema = schema

        # Extract connection parameters
        self.site_url = options.get("site_url")
        self.client_id = options.get("client_id")
        self.client_secret = options.get("client_secret")
        self.tenant_id = options.get("tenant_id")
        self.library_name = options.get("library_name")
        self.folder_path = options.get("folder_path")

        # Performance parameters
        self.batch_size = int(options.get("batch_size", "100"))
        self.max_partitions = int(options.get("max_partitions", "10"))

        # Validate required parameters
        required_params = ["site_url", "client_id", "client_secret", "tenant_id", "library_name"]
        missing_params = [param for param in required_params if not options.get(param)]
        if missing_params:
            raise ValueError(f"Missing required parameters: {missing_params}")

    def partitions(self) -> List[InputPartition]:
        """Plan input partitions for parallel processing"""
        from faker import Faker  # Import inside method for serialization

        # Initialize SharePoint client
        authenticator = SharePointAuthenticator(
            self.client_id, self.client_secret, self.tenant_id
        )
        client = SharePointAPIClient(self.site_url, authenticator)

        # Get all files from SharePoint
        all_files = client.list_files(self.library_name, self.folder_path)

        # Create partitions based on file count and size
        partition_size = max(1, len(all_files) // self.max_partitions)
        partitions = []

        for i in range(0, len(all_files), partition_size):
            file_batch = all_files[i:i + partition_size]
            partition = SharePointInputPartition(
                partition_id=len(partitions),
                file_list=file_batch,
                partition_params={
                    "site_url": self.site_url,
                    "client_id": self.client_id,
                    "client_secret": self.client_secret,
                    "tenant_id": self.tenant_id
                }
            )
            partitions.append(partition)

        return partitions

    def read(self, partition: SharePointInputPartition) -> Iterator[Tuple]:
        """Read data from SharePoint partition with error handling"""
        # Import libraries inside method for proper serialization
        from tenacity import retry, stop_after_attempt, wait_exponential
        import logging

        # Initialize clients within the executor
        authenticator = SharePointAuthenticator(
            partition.partition_params["client_id"],
            partition.partition_params["client_secret"],
            partition.partition_params["tenant_id"]
        )
        client = SharePointAPIClient(partition.partition_params["site_url"], authenticator)

        @retry(
            stop=stop_after_attempt(3),
            wait=wait_exponential(multiplier=1, min=2, max=10)
        )
        def process_file(file_info: Dict) -> Tuple:
            """Process individual file with retry logic"""
            try:
                # Download file content
                file_content = client.download_file(file_info['FileRef'])

                # Detect and process file format
                content_text = self._process_file_content(
                    file_content, file_info.get('FileLeafRef', '')
                )

                return (
                    file_info.get('FileLeafRef', ''),
                    file_info.get('FileRef', ''),
                    file_info.get('File', {}).get('Length', 0),
                    file_info.get('Modified'),
                    file_info.get('ContentType', ''),
                    content_text
                )

            except Exception as e:
                logging.error(f"Error processing file {file_info.get('FileRef')}: {e}")
                # Return record with error information
                return (
                    file_info.get('FileLeafRef', ''),
                    file_info.get('FileRef', ''),
                    0,
                    None,
                    "error",
                    f"Processing error: {str(e)}"
                )

        # Process all files in the partition
        for file_info in partition.file_list:
            try:
                yield process_file(file_info)
            except Exception as e:
                logging.error(f"Failed to process file after retries: {e}")
                continue

    def _process_file_content(self, content: bytes, file_name: str) -> str:
        """Process file content based on format"""
        file_extension = file_name.lower().split('.')[-1] if '.' in file_name else ''

        if file_extension == 'csv':
            return self._process_csv_content(content)
        elif file_extension == 'json':
            return self._process_json_content(content)
        elif file_extension == 'parquet':
            return self._process_parquet_content(content)
        else:
            # Default text processing
            try:
                return content.decode('utf-8')
            except UnicodeDecodeError:
                return f"Binary content ({len(content)} bytes)"

    def _process_csv_content(self, content: bytes) -> str:
        """Process CSV file content"""
        import csv
        from io import StringIO

        try:
            text_content = content.decode('utf-8')
            # Validate CSV structure
            csv_reader = csv.reader(StringIO(text_content))
            row_count = sum(1 for _ in csv_reader)
            return f"CSV file with {row_count} rows"
        except Exception as e:
            return f"CSV processing error: {e}"

    def _process_json_content(self, content: bytes) -> str:
        """Process JSON file content"""
        import json

        try:
            text_content = content.decode('utf-8')
            json_data = json.loads(text_content)
            return json.dumps(json_data, indent=2)
        except Exception as e:
            return f"JSON processing error: {e}"

    def _process_parquet_content(self, content: bytes) -> str:
        """Process Parquet file content"""
        try:
            import pyarrow.parquet as pq
            from io import BytesIO

            parquet_file = pq.ParquetFile(BytesIO(content))
            schema_info = str(parquet_file.schema)
            num_rows = parquet_file.metadata.num_rows
            return f"Parquet file: {num_rows} rows, Schema: {schema_info}"
        except Exception as e:
            return f"Parquet processing error: {e}"
```

The **partition-aware implementation** enables parallel processing across multiple Spark executors. Each partition processes a subset of SharePoint files independently, maximizing throughput and resource utilization.

## Comprehensive error handling and retry strategies

Production SharePoint connectors require **robust error handling** to manage network failures, authentication issues, and data processing errors. The tenacity library provides sophisticated retry mechanisms with exponential backoff and error classification.

```python
from tenacity import (
    retry, stop_after_attempt, wait_exponential, 
    retry_if_exception_type, before_sleep_log
)
import logging
from typing import Dict, Any
import requests

class SharePointErrorHandler:
    """Comprehensive error handling for SharePoint operations"""

    # Define retriable vs non-retriable exceptions
    RETRIABLE_EXCEPTIONS = (
        requests.exceptions.ConnectionError,
        requests.exceptions.Timeout,
        requests.exceptions.HTTPError,
        requests.exceptions.ReadTimeout
    )

    AUTHENTICATION_EXCEPTIONS = (
        requests.exceptions.HTTPError,  # 401, 403 errors
    )

    @staticmethod
    def is_retriable_http_error(exception: Exception) -> bool:
        """Determine if HTTP error is retriable"""
        if isinstance(exception, requests.exceptions.HTTPError):
            if hasattr(exception, 'response') and exception.response:
                status_code = exception.response.status_code
                # Retry on server errors and rate limiting
                return status_code >= 500 or status_code == 429
        return False

    @classmethod
    def create_retry_decorator(cls, operation_type: str = "general"):
        """Create appropriate retry decorator for operation type"""
        if operation_type == "authentication":
            return retry(
                stop=stop_after_attempt(3),
                wait=wait_exponential(multiplier=1, min=2, max=30),
                retry=retry_if_exception_type(cls.AUTHENTICATION_EXCEPTIONS),
                before_sleep=before_sleep_log(logging.getLogger(), logging.WARNING)
            )
        elif operation_type == "file_download":
            return retry(
                stop=stop_after_attempt(5),
                wait=wait_exponential(multiplier=1, min=4, max=60),
                retry=retry_if_exception_type(cls.RETRIABLE_EXCEPTIONS),
                before_sleep=before_sleep_log(logging.getLogger(), logging.WARNING)
            )
        else:
            return retry(
                stop=stop_after_attempt(3),
                wait=wait_exponential(multiplier=1, min=2, max=20),
                retry=retry_if_exception_type(cls.RETRIABLE_EXCEPTIONS)
            )

class ResilientSharePointClient(SharePointAPIClient):
    """SharePoint client with comprehensive error handling"""

    def __init__(self, site_url: str, authenticator: SharePointAuthenticator):
        super().__init__(site_url, authenticator)
        self.error_handler = SharePointErrorHandler()

    @SharePointErrorHandler.create_retry_decorator("file_download")
    def download_file_resilient(self, file_url: str) -> bytes:
        """Download file with comprehensive retry logic"""
        try:
            return super().download_file(file_url)
        except requests.exceptions.HTTPError as e:
            if e.response and e.response.status_code == 401:
                # Force token refresh for authentication errors
                self.authenticator._token_cache.clear()
                return super().download_file(file_url)
            raise

    @SharePointErrorHandler.create_retry_decorator("general")
    def list_files_resilient(self, library_name: str, folder_path: str = None) -> List[Dict]:
        """List files with error handling"""
        return super().list_files(library_name, folder_path)

    def process_files_with_error_collection(self, file_list: List[Dict]) -> Tuple[List[Dict], List[Dict]]:
        """Process files and collect errors separately"""
        successful_files = []
        failed_files = []

        for file_info in file_list:
            try:
                content = self.download_file_resilient(file_info['FileRef'])
                file_info['content'] = content
                file_info['status'] = 'success'
                successful_files.append(file_info)

            except Exception as e:
                error_info = {
                    'file_info': file_info,
                    'error': str(e),
                    'error_type': type(e).__name__,
                    'status': 'failed'
                }
                failed_files.append(error_info)
                logging.error(f"Failed to process file {file_info.get('FileRef')}: {e}")

        return successful_files, failed_files
```

**Token management** requires special attention in distributed environments. Spark executors may run on different machines, requiring careful coordination of authentication state and token refresh operations.

## Advanced partitioning and performance optimization

**Intelligent partitioning strategies** significantly impact performance in large SharePoint environments. The connector should analyze file sizes, folder structures, and cluster resources to determine optimal partition boundaries.

```python
class SharePointPartitionStrategy:
    """Advanced partitioning strategies for SharePoint data"""

    def __init__(self, target_partition_size_mb: int = 150, max_partitions: int = 1000):
        self.target_partition_size_mb = target_partition_size_mb
        self.max_partitions = max_partitions

    def calculate_optimal_partitions(self, file_list: List[Dict], cluster_cores: int = 50) -> List[List[Dict]]:
        """Calculate optimal partitioning based on file sizes and cluster capacity"""

        # Analyze file size distribution
        total_size_bytes = sum(f.get('File', {}).get('Length', 0) for f in file_list)
        total_size_mb = total_size_bytes / (1024 * 1024)

        # Calculate partition count based on size
        size_based_partitions = max(1, int(total_size_mb / self.target_partition_size_mb))

        # Calculate partition count based on cluster capacity
        core_based_partitions = cluster_cores * 2  # 2 tasks per core

        # Use the smaller value to avoid over-partitioning
        optimal_partitions = min(size_based_partitions, core_based_partitions, self.max_partitions)

        # Group files into partitions
        if len(file_list) <= optimal_partitions:
            # One file per partition if we have more partitions than files
            return [[f] for f in file_list]

        # Distribute files across partitions considering size balance
        return self._balance_partitions_by_size(file_list, optimal_partitions)

    def _balance_partitions_by_size(self, file_list: List[Dict], num_partitions: int) -> List[List[Dict]]:
        """Balance partitions by file size to prevent data skew"""

        # Sort files by size (descending)
        sorted_files = sorted(
            file_list,
            key=lambda f: f.get('File', {}).get('Length', 0),
            reverse=True
        )

        # Initialize partitions with size tracking
        partitions = [[] for _ in range(num_partitions)]
        partition_sizes = [0] * num_partitions

        # Distribute files using greedy algorithm
        for file_info in sorted_files:
            file_size = file_info.get('File', {}).get('Length', 0)

            # Find partition with smallest current size
            min_partition_idx = partition_sizes.index(min(partition_sizes))

            # Add file to that partition
            partitions[min_partition_idx].append(file_info)
            partition_sizes[min_partition_idx] += file_size

        # Remove empty partitions
        return [p for p in partitions if p]

class OptimizedSharePointReader(SharePointDataSourceReader):
    """Enhanced reader with advanced partitioning and caching"""

    def __init__(self, options: Dict[str, str], schema: StructType):
        super().__init__(options, schema)
        self.partition_strategy = SharePointPartitionStrategy(
            target_partition_size_mb=int(options.get("target_partition_size_mb", "150")),
            max_partitions=int(options.get("max_partitions", "1000"))
        )
        self.enable_caching = options.get("enable_caching", "true").lower() == "true"

    def partitions(self) -> List[InputPartition]:
        """Enhanced partitioning with size-based optimization"""
        authenticator = SharePointAuthenticator(
            self.client_id, self.client_secret, self.tenant_id
        )
        client = SharePointAPIClient(self.site_url, authenticator)

        # Get all files with metadata
        all_files = client.list_files(self.library_name, self.folder_path)

        # Calculate optimal partitions
        cluster_cores = int(self.options.get("cluster_cores", "50"))
        balanced_partitions = self.partition_strategy.calculate_optimal_partitions(
            all_files, cluster_cores
        )

        # Create InputPartition objects
        partitions = []
        for i, file_batch in enumerate(balanced_partitions):
            partition = SharePointInputPartition(
                partition_id=i,
                file_list=file_batch,
                partition_params={
                    "site_url": self.site_url,
                    "client_id": self.client_id,
                    "client_secret": self.client_secret,
                    "tenant_id": self.tenant_id,
                    "enable_caching": self.enable_caching
                }
            )
            partitions.append(partition)

        return partitions
